function HistoryScreen({data,go,saveSession,removeSession}){const[editing,setEditing]=useState(null);return <div className="screen light history-screen"><ScreenHeader title="History" go={go}/>{data.sessions.length===0?<Empty icon={<History size={21}/>} title="No sessions yet" text="Completed pumping sessions will appear here."/>:<div className="history-card">{data.sessions.map(session=><div className="history-row editable-history" key={session.id}><span className="history-time"><strong>{fmtTime(session.startedAt)}</strong><small>{fmtDate(session.startedAt)} · {fmtDuration(session.durationSec)}</small></span><strong className="history-ounces">{Number(session.ounces).toFixed(1)} oz</strong><span className="history-sides">{session.leftOz!=null?<small>L {Number(session.leftOz).toFixed(1)} · R {Number(session.rightOz).toFixed(1)}</small>:<small>{session.pumpType||session.tag}</small>}</span><button onClick={()=>setEditing(session)} aria-label="Edit session"><Pencil size={14}/></button><button onClick={()=>{if(confirm('Delete this pumping session?'))removeSession(session.id)}} aria-label="Delete session"><Trash2 size={14}/></button></div>)}</div>}{editing&&<EditSessionModal session={editing} onClose={()=>setEditing(null)} onSave={session=>{saveSession(session);setEditing(null)}}/>}</div>}
function EditSessionModal({session,onClose,onSave}){const[ounces,setOunces]=useState(session.ounces),[notes,setNotes]=useState(session.notes||''),[type,setType]=useState(session.pumpType||'Regular');return <Modal title="Edit Session" onClose={onClose}><label>Ounces</label><Stepper value={ounces} setValue={setOunces} step={0.5} suffix="oz"/><label>Pump type</label><select value={type} onChange={e=>setType(e.target.value)}><option>Regular</option><option>Power Pump</option><option>Manual</option><option>Nursing + Pumping</option></select><label>Notes</label><textarea value={notes} onChange={e=>setNotes(e.target.value)}/><button className="primary-cta" onClick={()=>onSave({...session,ounces:Number(ounces),pumpType:type,notes})}>Save Changes</button></Modal>}

function RemindersScreen({data,go,updateReminders}) {
  const r=data.reminders,[permission,setPermission]=useState(()=>('Notification'in window?Notification.permission:'unsupported')),[tempMinutes,setTempMinutes]=useState(r.temporary?.intervalMinutes||120),next=getNextReminder(r,data.sessions)
  const syncPush=()=>setTimeout(()=>{try{window.MilkyMamaPush?.sync?.()}catch{}},350)
  const enable=async value=>{if(!value){updateReminders({enabled:false});syncPush();return}try{const support=window.MilkyMamaPush?.supportState?.();if(support&&!support.supported){alert(support.reason);return}const result=window.MilkyMamaPush?.requestPermission?await window.MilkyMamaPush.requestPermission():await Notification.requestPermission();setPermission(result);if(result==='granted'){updateReminders({enabled:true,anchorAt:r.anchorAt||Date.now()});syncPush()}}catch(error){alert(error?.message||'Notifications could not be enabled.')}}
  const setMode=mode=>{updateReminders({mode,anchorAt:mode!=='times'?(r.anchorAt||Date.now()):r.anchorAt});syncPush()}
  const applyToday=()=>{const until=new Date();until.setHours(23,59,59,999);updateReminders({temporary:{intervalMinutes:Number(tempMinutes),until:until.toISOString()}});syncPush()}
  return <div className="screen light reminders-screen"><ScreenHeader title="Pumping Reminders" go={go} back="settings"/><section className="reminder-hero"><div className="reminder-hero-icon"><Bell size={24}/></div><div><strong>Stay on your pumping schedule</strong><p>Use a smart day/night rhythm, one interval, or exact daily times.</p></div><Switch checked={r.enabled} onChange={enable}/></section><div className={`permission-card permission-${permission}`}><span><strong>Notifications</strong><small>{permissionLabel(permission)}</small></span>{permission==='default'&&<button onClick={()=>enable(true)}>Allow</button>}</div><Segmented value={r.mode} onChange={setMode} options={[["smart","Smart"],["interval","Interval"],["times","Times"]]}/>{r.mode==='smart'&&<section className="reminder-panel"><div className="reminder-panel-heading"><Clock3 size={18}/><div><strong>Day and night schedule</strong><small>Intervals restart from the end of your latest pumping session.</small></div></div><FormRow label="Day starts"><input type="time" value={r.smart.dayStart} onChange={e=>updateReminders({smart:{...r.smart,dayStart:e.target.value}})}/></FormRow><FormRow label="Day interval"><MinutesSelect value={r.smart.dayIntervalMinutes} onChange={v=>updateReminders({smart:{...r.smart,dayIntervalMinutes:v}})}/></FormRow><FormRow label="Night starts"><input type="time" value={r.smart.nightStart} onChange={e=>updateReminders({smart:{...r.smart,nightStart:e.target.value}})}/></FormRow><FormRow label="Night interval"><MinutesSelect value={r.smart.nightIntervalMinutes} onChange={v=>updateReminders({smart:{...r.smart,nightIntervalMinutes:v}})}/></FormRow></section>}{r.mode==='interval'&&<section className="reminder-panel"><div className="reminder-panel-heading"><Clock3 size={18}/><div><strong>Repeat after last pump</strong><small>The next interval starts when your latest session ends.</small></div></div><FormRow label="Repeat every"><MinutesSelect value={r.intervalMinutes} onChange={v=>updateReminders({intervalMinutes:v,anchorAt:Date.now()})}/></FormRow></section>}{r.mode==='times'&&<section className="reminder-panel"><div className="reminder-panel-heading"><Clock3 size={18}/><div><strong>Daily reminder times</strong><small>Choose the exact times you want each day.</small></div></div><div className="reminder-time-list">{r.times.map((time,index)=><div className="reminder-time-row" key={`${time}-${index}`}><input type="time" value={time} onChange={e=>{const nextTimes=[...r.times];nextTimes[index]=e.target.value;updateReminders({times:[...new Set(nextTimes.filter(Boolean))].sort()})}}/><button onClick={()=>updateReminders({times:r.times.filter((_,i)=>i!==index)})} aria-label="Remove time"><Trash2 size={15}/></button></div>)}</div><button className="add-reminder-time" onClick={()=>r.times.length<12&&updateReminders({times:[...r.times,'12:00'].sort()})}><Plus size={15}/> Add Time</button></section>}<section className="temporary-card"><div><strong>Change today only</strong><small>Temporarily use a different interval until midnight.</small></div><MinutesSelect value={tempMinutes} onChange={setTempMinutes}/><button onClick={applyToday}>Apply today</button>{r.temporary&&new Date(r.temporary.until)>new Date()&&<button className="text-action" onClick={()=>updateReminders({temporary:null})}>Clear temporary schedule</button>}</section><section className="next-reminder-card"><span>Next Reminder</span><strong>{r.enabled&&next?formatReminderDate(next):'Not scheduled'}</strong>{r.enabled&&next&&<small>{relativeFuture(next)}</small>}</section></div>
}

function SettingsScreen({data,go,setData,updateSettings,installPrompt,cloudState}) {
  const[cloudModal,setCloudModal]=useState(false),exportJson=()=>downloadText('milky-mama-data.json',JSON.stringify(data,null,2),'application/json'),exportCsv=()=>downloadText('milky-mama-sessions.csv',sessionsCsv(data),'text/csv'),copyKey=async()=>{await navigator.clipboard.writeText(getCloudKey());alert('Sync key copied. Keep it private.')},resync=async()=>{try{const remote=await pullCloud();if(remote.found&&remote.payload)setData(current=>mergeCloudData(current,remote.payload));else await pushCloud(data)}catch(error){alert(error?.message||'Could not sync.')}}
  return <div className="screen light settings-screen"><ScreenHeader title="Settings" go={go}/><button className="settings-reminder-link" onClick={()=>go('reminders')}><span className="settings-reminder-icon"><Bell size={17}/></span><span><strong>Pumping Reminders</strong><small>{data.reminders.enabled?reminderSummary(data.reminders):'Off'}</small></span><ChevronRight size={14}/></button><section className="cloud-card"><span className="cloud-icon">{cloudState.status==='error'?<CloudOff size={18}/>:<Cloud size={18}/>}</span><div><strong>Private cloud backup</strong><small>{cloudState.message} · {maskCloudKey()}</small></div><Switch checked={data.settings.cloudSync} onChange={value=>updateSettings({cloudSync:value})}/><div className="cloud-actions"><button onClick={copyKey}><Copy size={13}/> Copy sync key</button><button onClick={resync}><RefreshCw size={13}/> Sync now</button><button onClick={()=>setCloudModal(true)}>Link another key</button></div></section><div className="settings-list"><SettingRow label="Daily Goal"><input type="number" min="1" value={data.settings.dailyGoal} onChange={e=>updateSettings({dailyGoal:Number(e.target.value||24)})}/></SettingRow><SettingRow label="Haptics"><Switch checked={data.settings.haptics} onChange={v=>updateSettings({haptics:v})}/></SettingRow><SettingRow label="Sounds"><Switch checked={data.settings.sounds} onChange={v=>updateSettings({sounds:v})}/></SettingRow><SettingRow label="Reduce Motion"><Switch checked={data.settings.reduceMotion} onChange={v=>updateSettings({reduceMotion:v})}/></SettingRow></div><div className="settings-actions"><button onClick={exportJson}><FileText size={15}/><span>Export Data (JSON)</span><ChevronRight size={14}/></button><button onClick={exportCsv}><Download size={15}/><span>Export Sessions (CSV)</span><ChevronRight size={14}/></button><button onClick={()=>window.print()}><Share2 size={15}/><span>Print or Save Report</span><ChevronRight size={14}/></button><button className="danger" onClick={()=>{if(confirm('Delete all Milky Mama data on this device? Cloud backup will be replaced with the empty app state if sync stays on.'))setData(defaultData)}}><Trash2 size={15}/><span>Delete All Data</span></button></div>{installPrompt?<button className="install-row" onClick={()=>installPrompt.prompt()}><Download size={16}/><span>Install Milky Mama</span><ChevronRight size={14}/></button>:<p className="install-help">On iPhone, open Milky Mama in Safari, tap Share, then Add to Home Screen. Home Screen installation is required for Web Push notifications.</p>}{cloudModal&&<CloudKeyModal onClose={()=>setCloudModal(false)} onConnect={async key=>{try{setCloudKey(key);const remote=await pullCloud();if(remote.found&&remote.payload)setData(current=>mergeCloudData(current,remote.payload));else await pushCloud(data);setCloudModal(false)}catch(error){alert(error?.message||'Could not link that sync key.')}}}/>}</div>
}
function CloudKeyModal({onClose,onConnect}){const[value,setValue]=useState('');return <Modal title="Link Cloud Backup" onClose={onClose}><p className="modal-copy">Enter the private sync key from the other Milky Mama installation. This replaces the sync identity on this device.</p><label>Sync key</label><input value={value} onChange={e=>setValue(e.target.value)} autoCapitalize="none" autoCorrect="off"/><button className="primary-cta" onClick={()=>onConnect(value)}>Link Backup</button></Modal>}
function SettingRow({label,children}){return <div className="setting-row"><span>{label}</span>{children}</div>}

function AchievementsScreen({data,go}){const achievements=getAchievements(data),unlocked=achievements.filter(i=>i.unlocked);return <div className="screen light achievements-screen"><ScreenHeader title="Achievements" go={go}/><p className="center-meta">{unlocked.length} / {achievements.length} Unlocked</p><div className="achievement-list">{achievements.map(item=><AchievementRow key={item.id} item={item}/>)}</div></div>}
function AchievementRow({item}){const Icon=ACHIEVEMENT_ICONS[item.id]||Trophy;return <div className={`achievement-row ${item.unlocked?'unlocked':''}`}><span className={`achievement-icon badge-${item.id}`}><Icon size={20}/></span><span><strong>{item.title}</strong><small>{item.desc}</small></span>{item.unlocked?<span className="check-pill"><Check size={13}/></span>:<span className="achievement-progress">{item.progress}</span>}</div>}
function AchievementBadge({item}){const Icon=ACHIEVEMENT_ICONS[item.id]||Trophy;return <div><span className={`badge badge-${item.id} ${item.unlocked?'unlocked':''}`}><Icon size={25}/></span><small>{item.title}</small></div>}
function GardenScreen({data,go}){const xp=data.sessions.length*12+Math.round(data.sessions.reduce((sum,s)=>sum+Number(s.ounces),0)),level=Math.max(1,Math.floor(xp/60)+1),inLevel=xp%60,blooms=Math.min(5,Math.floor((data.sessions.length+2)/3));return <div className="screen garden-screen"><ScreenHeader title="Milky Garden" go={go}/><p className="garden-subtitle">Keep going, your garden is growing.</p><div className="garden-scene"><div className="garden-pots">{Array.from({length:5},(_,i)=><GardenPot key={i} active={i<blooms} index={i}/>)}</div><div className="garden-grass"/></div><div className="garden-progress-card"><strong>Garden Progress</strong><div className="garden-progress-meta"><span>Level {level}</span><span>{inLevel} / 60 XP</span></div><div className="xp-track"><div style={{width:`${inLevel/60*100}%`}}/></div></div></div>}
function GardenPot({active,index}){return <div className={`garden-pot pot-${index} ${active?'active':''}`}>{active&&<div className="plant-stem"><Flower2 size={index%2?42:36}/></div>}<div className="pot-rim"/><div className="pot-body"/></div>}

function storageDeadline(item){const base=item.thawedAt?new Date(item.thawedAt):new Date(item.storedAt),ms=item.thawedAt?24*3600000:item.location==='Room'?4*3600000:item.location==='Fridge'?4*86400000:180*86400000;return new Date(base.getTime()+ms)}
function stashStatus(item){const deadline=storageDeadline(item),remaining=deadline-Date.now(),day=86400000,hour=3600000;let label='Good',tone='good';if(remaining<=0){label='Past guide';tone='soon'}else if(remaining<(item.location==='Room'||item.thawedAt?2*hour:day)){label='Use Soon';tone='soon'}else if(item.location==='Fridge'||item.thawedAt){label='Fresh';tone='fresh'}return{label,tone,deadline,prefix:item.location==='Freezer'&&!item.thawedAt?'Best by':'Use by'}}
function getUseSoon(stash){return stash.filter(item=>stashStatus(item).tone==='soon')}
function sumStash(stash){return stash.reduce((sum,item)=>sum+Number(item.ounces||0),0)}
function sumLocation(stash,location){return stash.filter(i=>i.location===location).reduce((sum,i)=>sum+Number(i.ounces||0),0)}
function toClock(sec){const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function relativeTime(date){const mins=Math.floor((Date.now()-date.getTime())/60000);if(mins<1)return'Just now';if(mins<60)return`${mins}m ago`;const h=Math.floor(mins/60);if(h<24)return`${h}h ${mins%60}m ago`;return`${Math.floor(h/24)}d ago`}
function relativeFuture(date){const mins=Math.max(0,Math.ceil((date.getTime()-Date.now())/60000));if(mins<60)return`in ${mins} min`;const h=Math.floor(mins/60),m=mins%60;return m?`in ${h}h ${m}m`:`in ${h}h`}
function calcStreak(sessions){const days=[...new Set(sessions.map(s=>new Date(s.startedAt).toDateString()))];let streak=0,date=new Date();for(let i=0;i<365;i++){if(days.includes(date.toDateString()))streak++;else if(i>0)break;date.setDate(date.getDate()-1)}return streak}
function dailyBuckets(sessions,count){const result=[];for(let i=count-1;i>=0;i--){const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-i);const end=new Date(start);end.setDate(end.getDate()+1);const value=sessions.filter(s=>{const d=new Date(s.startedAt);return d>=start&&d<end}).reduce((sum,s)=>sum+Number(s.ounces||0),0);result.push({label:start.toLocaleDateString(undefined,{weekday:'narrow'}),value})}return result}
function getAchievements(data){const count=data.sessions.length,total=data.sessions.reduce((sum,s)=>sum+Number(s.ounces||0),0),streak=calcStreak(data.sessions),stored=sumStash(data.stash);return[{id:'first',title:'First Drop',desc:'Log your first session',unlocked:count>=1,progress:`${count}/1`},{id:'start',title:'Getting Started',desc:'Log 5 sessions',unlocked:count>=5,progress:`${Math.min(count,5)}/5`},{id:'track',title:'Keeping Track',desc:'Log 25 sessions',unlocked:count>=25,progress:`${Math.min(count,25)}/25`},{id:'routine',title:'Routine Builder',desc:'Reach a 3 day logging streak',unlocked:streak>=3,progress:`${Math.min(streak,3)}/3`},{id:'stash',title:'Stash Starter',desc:'Store 20 ounces',unlocked:stored>=20,progress:`${Math.min(Math.round(stored),20)}/20`},{id:'fifty',title:'Fifty Ounces',desc:'Pump 50 ounces total',unlocked:total>=50,progress:`${Math.min(Math.round(total),50)}/50`}]}
function isDayClock(date,smart){const min=date.getHours()*60+date.getMinutes(),parse=v=>{const[h,m]=String(v).split(':').map(Number);return h*60+m},start=parse(smart.dayStart||'06:00'),end=parse(smart.nightStart||'22:00');return start<end?min>=start&&min<end:min>=start||min<end}
function nextSmart(r,anchor,now){let cursor=new Date(anchor),guard=0;while(guard++<2000){const temp=r.temporary&&new Date(r.temporary.until)>cursor?r.temporary:null,mins=temp?Number(temp.intervalMinutes):isDayClock(cursor,r.smart)?Number(r.smart.dayIntervalMinutes):Number(r.smart.nightIntervalMinutes),due=new Date(cursor.getTime()+clamp(mins,15,1440)*60000);if(due>now)return due;cursor=due}return new Date(now.getTime()+180*60000)}
function getNextReminder(r,sessions,now=new Date()){if(!r?.enabled)return null;if(r.mode==='times'){const times=[...new Set((r.times||[]).filter(Boolean))].sort();for(const time of times){const[h,m]=time.split(':').map(Number),candidate=new Date(now);candidate.setHours(h,m,0,0);if(candidate>now)return candidate}if(!times.length)return null;const[h,m]=times[0].split(':').map(Number),tomorrow=new Date(now);tomorrow.setDate(tomorrow.getDate()+1);tomorrow.setHours(h,m,0,0);return tomorrow}const latest=sessions?.[0],sessionAnchor=latest?sessionEnd(latest):null,anchor=Number(r.anchorAt||sessionAnchor||now.getTime());if(r.mode==='smart')return nextSmart(r,anchor,now);const ms=clamp(r.intervalMinutes||180,15,1440)*60000,elapsed=Math.max(0,now.getTime()-anchor),steps=Math.floor(elapsed/ms)+1;return new Date(anchor+steps*ms)}
function formatReminderDate(date){const now=new Date(),tomorrow=new Date(now);tomorrow.setDate(now.getDate()+1);const prefix=date.toDateString()===now.toDateString()?'Today':date.toDateString()===tomorrow.toDateString()?'Tomorrow':date.toLocaleDateString(undefined,{month:'short',day:'numeric'});return`${prefix}, ${date.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}`}
function formatInterval(minutes){const total=clamp(minutes||15,15,1440),h=Math.floor(total/60),m=total%60;if(!h)return`Every ${m} minutes`;if(!m)return`Every ${h} ${h===1?'hour':'hours'}`;return`Every ${h}h ${m}m`}
function formatIntervalShort(minutes){const h=Math.floor(minutes/60),m=Math.round(minutes%60);return h?`${h}h ${m}m`:`${m}m`}
function reminderSummary(r){if(r.mode==='times')return`${r.times.length} daily ${r.times.length===1?'time':'times'}`;if(r.mode==='smart')return`${formatInterval(r.smart.dayIntervalMinutes)} day · ${formatInterval(r.smart.nightIntervalMinutes)} night`;return formatInterval(r.intervalMinutes)}
function permissionLabel(p){if(p==='granted')return'Allowed on this device';if(p==='denied')return'Blocked in iPhone Settings';if(p==='unsupported')return'Install to iPhone Home Screen to enable push';return'Permission required'}
function averageInterval(sessions){if(sessions.length<2)return 0;const sorted=[...sessions].sort((a,b)=>new Date(a.startedAt)-new Date(b.startedAt));let total=0,count=0;for(let i=1;i<sorted.length;i++){const diff=(new Date(sorted[i].startedAt)-new Date(sorted[i-1].startedAt))/60000;if(diff>0&&diff<1440){total+=diff;count++}}return count?total/count:0}
function bestTimeOfDay(sessions){if(!sessions.length)return'Not enough data';const buckets={Morning:[],Afternoon:[],Evening:[],Overnight:[]};sessions.forEach(s=>{const h=new Date(s.startedAt).getHours(),key=h>=5&&h<12?'Morning':h>=12&&h<17?'Afternoon':h>=17&&h<22?'Evening':'Overnight';buckets[key].push(Number(s.ounces||0))});const scored=Object.entries(buckets).filter(([,v])=>v.length).map(([k,v])=>[k,v.reduce((a,b)=>a+b,0)/v.length]).sort((a,b)=>b[1]-a[1]);return scored[0]?.[0]||'Not enough data'}
function sideTotals(sessions){return sessions.reduce((a,s)=>{if(s.leftOz!=null){a.left+=Number(s.leftOz||0);a.right+=Number(s.rightOz||0);a.total++}return a},{left:0,right:0,total:0})}
function durationInsight(sessions){const usable=sessions.filter(s=>Number(s.durationSec)>0&&Number(s.ounces)>0);if(usable.length<3)return'Log at least three sessions with duration and output to compare efficiency.';const short=usable.filter(s=>s.durationSec<=1200),long=usable.filter(s=>s.durationSec>1200),avg=a=>a.length?a.reduce((sum,s)=>sum+Number(s.ounces),0)/a.length:0;if(!short.length||!long.length)return`Your average session produces ${(usable.reduce((sum,s)=>sum+Number(s.ounces),0)/usable.length).toFixed(1)} oz.`;return avg(long)>avg(short)?`Sessions over 20 minutes average ${(avg(long)-avg(short)).toFixed(1)} oz more than shorter sessions.`:'Shorter sessions are currently producing about as much as longer sessions.'}
function projectEndOfDay(sessions){const today=sessions.filter(s=>sameDay(s.startedAt)),produced=today.reduce((sum,s)=>sum+Number(s.ounces||0),0);if(!today.length)return 0;const now=new Date(),hours=Math.max(1,now.getHours()+now.getMinutes()/60),rate=produced/hours;return Math.min(produced+rate*(24-hours),produced*3)}
function buildTodaySchedule(r,sessions){const now=new Date(),items=[],todaySessions=sessions.filter(s=>sameDay(s.startedAt)).sort((a,b)=>new Date(a.startedAt)-new Date(b.startedAt));todaySessions.forEach(s=>items.push({date:new Date(s.startedAt),time:fmtTime(s.startedAt),label:'Pumped',status:'completed',ounces:Number(s.ounces||0)}));if(r.enabled){if(r.mode==='times'){(r.times||[]).forEach(time=>{const[h,m]=time.split(':').map(Number),d=new Date();d.setHours(h,m,0,0);if(!todaySessions.some(s=>Math.abs(new Date(s.startedAt)-d)<45*60000))items.push({date:d,time:d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}),label:'Pump',status:d>now?'scheduled':'missed',ounces:0})})}else{let cursor=getNextReminder(r,sessions,now);for(let i=0;cursor&&i<6&&sameDay(cursor);i++){items.push({date:new Date(cursor),time:cursor.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}),label:'Pump',status:i===0?'next':'scheduled',ounces:0});cursor=r.mode==='smart'?nextSmart(r,cursor,new Date(cursor.getTime()+1)):new Date(cursor.getTime()+clamp(r.intervalMinutes,15,1440)*60000)}}}return items.sort((a,b)=>a.date-b.date)}
function sessionsCsv(data){const esc=v=>`"${String(v??'').replace(/"/g,'""')}"`,rows=[['Date','Time','Ounces','Duration Minutes','Left Oz','Right Oz','Pump Type','Tag','Notes'],...data.sessions.map(s=>[fmtDate(s.startedAt),fmtTime(s.startedAt),Number(s.ounces||0).toFixed(2),Math.round(Number(s.durationSec||0)/60),s.leftOz??'',s.rightOz??'',s.pumpType||'',s.tag||'',s.notes||''])];return rows.map(row=>row.map(esc).join(',')).join('\n')}
function downloadText(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
